import Decimal from "decimal.js";
import type { BreakEvenResult } from "./breakeven";
import { roundMoney } from "./money";

/**
 * A plain-language verdict generated by rules, not AI (BUILD_PLAN.md
 * Phase 2, brought forward into Phase 1 so no static text sits next to
 * live numbers). It reads only engine results: the sign of the profit as
 * displayed (rounded to piastres) and the break-even on the *same* basis.
 */

export type Verdict =
  | { kind: "profitable"; occupancy: Decimal | null; breakEvenOccupancy: Decimal | null }
  | { kind: "at_break_even"; occupancy: Decimal | null }
  | { kind: "loss"; occupancy: Decimal | null; breakEvenOccupancy: Decimal }
  | { kind: "unreachable"; occupancy: Decimal | null; reason: "never_profitable" | "exceeds_available_nights" }
  | { kind: "no_available_nights" };

export interface VerdictInput {
  /** The profit figure the verdict sits next to. */
  profit: Decimal.Value;
  /** Displayed occupancy (already capped at 100%). */
  occupancy: Decimal | null;
  /** Break-even on the same cost basis as `profit`. */
  breakEven: BreakEvenResult;
}

export function generateVerdict({ profit, occupancy, breakEven }: VerdictInput): Verdict {
  if (breakEven.kind === "unreachable" && breakEven.reason === "no_available_nights") {
    return { kind: "no_available_nights" };
  }
  const shown = roundMoney(profit);
  const breakEvenOccupancy = breakEven.kind === "reached" ? breakEven.occupancy : null;
  if (shown.isZero()) return { kind: "at_break_even", occupancy };
  if (shown.greaterThan(0)) return { kind: "profitable", occupancy, breakEvenOccupancy };
  if (breakEven.kind === "reached") return { kind: "loss", occupancy, breakEvenOccupancy: breakEven.occupancy };
  // "no_available_nights" returned above; TypeScript does not narrow across the two checks.
  return { kind: "unreachable", occupancy, reason: breakEven.reason as "never_profitable" | "exceeds_available_nights" };
}
